import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStream in = new BufferedInputStream(System.in, 1 << 16);
        long total = 0, sevens = 0;
        int c;
        while ((c = in.read()) != -1) {
            if (c < '0' || c > '9') continue;
            total += c - '0';  // n mod 3 == digit sum mod 3
            if (c == '7') sevens++;
        }
        System.out.println(total % 3 == 0 && sevens >= 2 ? 1 : 0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	s := readToken()
	total, sevens := 0, 0
	for i := 0; i < len(s); i++ {
		total += int(s[i] - '0') // n mod 3 == digit sum mod 3
		if s[i] == '7' {
			sevens++
		}
	}
	if total%3 == 0 && sevens >= 2 {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}
